=== FILE: skid_buffer.v ===
// skid_buffer: register slice for one valid/ready stream.
// Implements interface_spec.md (skid_buffer) per microarchitecture.md:
// an output register (m_valid/m_data) and a skid register
// (skid_valid/skid_data). Every output is a flop or the inverse of one.
`default_nettype none

module skid_buffer #(
    parameter integer WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    // upstream
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    // downstream
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    // Output register may load on this edge.
    wire m_free = !m_valid || m_ready;
    // Upstream transfer on this edge.
    wire s_fire = s_valid && s_ready;

    // At most one beat held <=> skid register empty.
    assign s_ready = !skid_valid;

    // Control state (reset).
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else if (m_free) begin
            if (skid_valid) begin
                m_valid    <= 1'b1;   // skid beat moves to the output
                skid_valid <= 1'b0;
            end else begin
                m_valid    <= s_valid; // input beat, if any, goes straight out
            end
        end else if (s_fire) begin
            skid_valid <= 1'b1;       // output stalled: catch the beat
        end
    end

    // Data registers (no reset). Each loads only in its control's row.
    always @(posedge clk) begin
        if (m_free) begin
            if (skid_valid)
                m_data <= skid_data;
            else
                m_data <= s_data;
        end
        if (!m_free && s_fire)
            skid_data <= s_data;
    end

`ifdef FORMAL
    // Design-intent assertions (checked only by a formal flow).
    reg f_past_valid = 1'b0;
    reg f_reset_done = 1'b0;
    always @(posedge clk) begin
        f_past_valid <= 1'b1;
        if (!rst_n)
            f_reset_done <= 1'b1;
    end

    // The skid register is only full while the output register is full.
    always @(*) begin
        if (f_reset_done)
            assert(!skid_valid || m_valid);
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            // Reset drops every beat.
            if (!$past(rst_n)) begin
                assert(!m_valid);
                assert(!skid_valid);
            end
            // Hold: an offered beat not taken stays, unchanged.
            if (f_reset_done && $past(f_reset_done) && $past(rst_n)
                && $past(m_valid) && !$past(m_ready)) begin
                assert(m_valid);
                assert(m_data == $past(m_data));
            end
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
