// skid_buffer_tb: self-checking testbench for skid_buffer.
// Two lanes (WIDTH 8 and WIDTH 1) share the same controls; lane 1 carries
// bit 0 of the lane-8 data. A two-entry queue model, moved only by the
// port handshakes, is compared with both lanes every cycle.
`timescale 1ns/1ps
`default_nettype none

module skid_buffer_tb;

    reg        clk     = 1'b0;
    reg        rst_n   = 1'b0;
    reg        s_valid = 1'b0;
    reg  [7:0] s_data  = 8'h00;
    reg        m_ready = 1'b0;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data[0:0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    always #5 clk = ~clk;

    // Reference model: queue of up to two beats.
    reg [1:0] cnt;
    reg [7:0] q0;
    reg [7:0] q1;

    integer passed;
    integer failed;
    integer accepted;
    integer delivered;
    integer dropped;
    integer base_acc;
    integer base_del;
    integer i;
    integer got;

    reg        sf;
    reg        mf;
    reg        r8;
    reg        r1;
    reg        v8;
    reg        v1;
    reg  [7:0] d8;
    reg  [0:0] d1;
    reg [31:0] rnd;
    reg  [7:0] seq;
    reg [8*64-1:0] nonce;

    task chk(input ok, input integer id);
        begin
            if (ok === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("skid_buffer_tb: check %0d failed at %0t", id, $time);
            end
        end
    endtask

    // Outputs agree with the model (both lanes).
    task check_outputs;
        begin
            chk(m_valid8 === (cnt != 2'd0), 1);
            chk(s_ready8 === (cnt != 2'd2), 2);
            chk(m_valid1 === (cnt != 2'd0), 3);
            chk(s_ready1 === (cnt != 2'd2), 4);
            if (cnt != 2'd0) begin
                chk(m_data8 === q0, 5);
                chk(m_data1 === q0[0:0], 6);
            end
        end
    endtask

    // One cycle. Called at posedge+1 with the inputs for this cycle set;
    // returns at the next posedge+1.
    task step;
        begin
            #1;
            check_outputs;
            // No output may move with m_ready, s_valid or s_data in a cycle.
            r8 = s_ready8;
            r1 = s_ready1;
            v8 = m_valid8;
            v1 = m_valid1;
            d8 = m_data8;
            d1 = m_data1;
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data  = ~s_data;
            #1;
            chk(s_ready8 === r8, 10);
            chk(s_ready1 === r1, 11);
            chk(m_valid8 === v8, 12);
            chk(m_valid1 === v1, 13);
            chk(m_data8  === d8, 14);
            chk(m_data1  === d1, 15);
            m_ready = ~m_ready;
            s_valid = ~s_valid;
            s_data  = ~s_data;
            #1;
            // Advance the model by the handshakes on the coming edge.
            if (rst_n !== 1'b1) begin
                dropped = dropped + {30'd0, cnt};
                cnt = 2'd0;
            end else begin
                sf = s_valid & (cnt != 2'd2);
                mf = m_ready & (cnt != 2'd0);
                if (mf) begin
                    q0  = q1;
                    cnt = cnt - 2'd1;
                    delivered = delivered + 1;
                end
                if (sf) begin
                    if (cnt == 2'd0)
                        q0 = s_data;
                    else
                        q1 = s_data;
                    cnt = cnt + 2'd1;
                    accepted = accepted + 1;
                end
            end
            @(posedge clk);
            #1;
        end
    endtask

    initial begin
        passed    = 0;
        failed    = 0;
        accepted  = 0;
        delivered = 0;
        dropped   = 0;
        base_acc  = 0;
        base_del  = 0;
        cnt       = 2'd0;
        q0        = 8'h00;
        q1        = 8'h00;
        seq       = 8'h00;
        nonce     = {8*64{1'b0}};

        // ---- Reset values ----
        @(posedge clk);
        @(posedge clk);
        #1;
        chk(m_valid8 === 1'b0, 20);
        chk(s_ready8 === 1'b1, 21);
        chk(m_valid1 === 1'b0, 22);
        chk(s_ready1 === 1'b1, 23);
        step;  // one more reset cycle under the model

        // ---- One-cycle latency ----
        rst_n   = 1'b1;
        s_valid = 1'b1;
        s_data  = 8'hA5;
        m_ready = 1'b1;
        chk(m_valid8 === 1'b0, 29);
        step;
        chk(m_valid8 === 1'b1, 30);
        chk(m_data8  === 8'hA5, 31);
        chk(m_valid1 === 1'b1, 32);
        chk(m_data1  === 1'b1, 33);
        s_valid = 1'b0;
        step;
        chk(m_valid8 === 1'b0, 34);
        chk(m_valid1 === 1'b0, 35);

        // ---- Full throughput ----
        base_del = delivered;
        base_acc = accepted;
        m_ready  = 1'b1;
        for (i = 0; i < 64; i = i + 1) begin
            s_valid = 1'b1;
            s_data  = seq;
            seq     = seq + 8'd1;
            if (i > 0) begin
                chk(s_ready8 === 1'b1, 40);
                chk(m_valid8 === 1'b1, 41);
                chk(s_ready1 === 1'b1, 42);
                chk(m_valid1 === 1'b1, 43);
            end
            step;
        end
        chk(delivered - base_del == 63, 44);
        chk(accepted - base_acc == 64, 45);
        s_valid = 1'b0;
        step;
        chk(m_valid8 === 1'b0, 46);
        chk(m_valid1 === 1'b0, 47);

        // ---- Stall: one held, a second is accepted; two held, a third is not ----
        base_acc = accepted;
        m_ready  = 1'b0;
        s_valid  = 1'b1;
        s_data   = 8'h11;
        step;
        chk(m_valid8 === 1'b1, 48);
        chk(m_data8  === 8'h11, 49);
        chk(s_ready8 === 1'b1, 50);
        chk(s_ready1 === 1'b1, 51);
        s_data = 8'h22;
        step;
        chk(s_ready8 === 1'b0, 52);
        chk(s_ready1 === 1'b0, 53);
        chk(m_data8  === 8'h11, 54);
        chk(m_data1  === 1'b1, 55);
        s_data = 8'h33;
        repeat (3) begin
            step;
            chk(s_ready8 === 1'b0, 56);
            chk(m_valid8 === 1'b1, 57);
            chk(m_data8  === 8'h11, 58);
            chk(m_data1  === 1'b1, 59);
        end
        chk(accepted - base_acc == 2, 60);

        // ---- Ready rises after the stall; every beat out in order, once ----
        m_ready = 1'b1;
        step;  // 0x11 leaves; 0x33 is not taken (s_ready was low)
        chk(s_ready8 === 1'b1, 61);
        chk(m_data8  === 8'h22, 62);
        chk(m_data1  === 1'b0, 63);
        chk(accepted - base_acc == 2, 64);
        step;  // 0x22 leaves; 0x33 enters
        chk(m_valid8 === 1'b1, 65);
        chk(m_data8  === 8'h33, 66);
        chk(m_data1  === 1'b1, 67);
        s_valid = 1'b0;
        step;
        chk(m_valid8 === 1'b0, 68);
        chk(m_valid1 === 1'b0, 69);
        chk(accepted - base_acc == 3, 70);

        // ---- Random traffic against the model ----
        for (i = 0; i < 3000; i = i + 1) begin
            rnd = $random;
            if (((i / 500) % 3) == 0) begin
                s_valid = rnd[0];
                m_ready = rnd[1];
            end else if (((i / 500) % 3) == 1) begin
                s_valid = rnd[0] | rnd[1] | rnd[2];
                m_ready = rnd[3] & rnd[4];
            end else begin
                s_valid = rnd[0] & rnd[1];
                m_ready = rnd[3] | rnd[4] | rnd[5];
            end
            s_data = rnd[15:8];
            step;
        end
        // drain
        s_valid = 1'b0;
        m_ready = 1'b1;
        repeat (3) step;
        chk(m_valid8 === 1'b0, 71);
        chk(m_valid1 === 1'b0, 72);
        chk(accepted == delivered, 73);

        // ---- Reset with beats held ----
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data  = 8'h5A;
        step;
        s_data  = 8'hC3;
        step;
        chk(m_valid8 === 1'b1, 80);
        chk(s_ready8 === 1'b0, 81);
        rst_n  = 1'b0;
        s_data = 8'h77;
        step;
        chk(m_valid8 === 1'b0, 82);
        chk(s_ready8 === 1'b1, 83);
        chk(m_valid1 === 1'b0, 84);
        chk(s_ready1 === 1'b1, 85);
        chk(dropped == 2, 86);
        rst_n   = 1'b1;
        s_valid = 1'b0;
        m_ready = 1'b1;
        step;
        chk(m_valid8 === 1'b0, 87);
        s_valid = 1'b1;
        s_data  = 8'h3C;
        step;
        chk(m_valid8 === 1'b1, 88);
        chk(m_data8  === 8'h3C, 89);
        s_valid = 1'b0;
        step;
        chk(m_valid8 === 1'b0, 90);
        chk(accepted == delivered + dropped, 91);

        // ---- Verdict ----
        got = $value$plusargs("nirmaan_nonce=%s", nonce);
        if (got == 0)
            nonce = {8*64{1'b0}};
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: a hung run ends without a verdict, which counts as a failure.
    initial begin
        #2000000;
        $error("skid_buffer_tb: timeout");
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
